def main():
    if not BLOB_DIR.is_dir():
        print("ERRORE: dir blob non trovata:", BLOB_DIR)
        print("Se il daemon girava con un'altra home, cercala con:")
        print(r"  dir /s /b C:\\*.bin | findstr _history")
        return 2
    blobs = {}
    for b in BLOB_DIR.glob("*.bin"):
        blobs.setdefault(b.stat().st_size, []).append(b)
    print("blob trovati:", sum(len(v) for v in blobs.values()), "in", BLOB_DIR)
    ok = amb = missing = skipped = 0
    for t in TARGETS:
        dst, size = Path(t["path"]), t["size"]
        if dst.exists():
            skipped += 1
            continue
        cands = blobs.get(size, [])
        if len(cands) == 1:
            if APPLY:
                dst.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(cands[0], dst)
            tag = "OK" if APPLY else "DRY"
            print("[" + tag + "]", dst.name, " <- ", cands[0].name[:16] + "...", "(", size, "B )")
            ok += 1
        elif not cands:
            print("[MANCA BLOB]", dst, "(", size, "B )")
            missing += 1
        else:
            print("[AMBIGUO", len(cands), "blob]", dst, "(", size, "B )")
            amb += 1
    print()
    extra = "" if APPLY else " (dry-run: aggiungi --apply)"
    print("esito:", ok, "ripristinabili" + extra + ",", skipped,
          "gia' presenti,", missing, "senza blob,", amb, "ambigui")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
